CREATE TABLE IF NOT EXISTS t_p83915249_biotech_anime_store.orbital_stations (id SERIAL PRIMARY KEY, planet_id INTEGER NOT NULL, player_id INTEGER NOT NULL, level INTEGER NOT NULL DEFAULT 1, shipyard_level INTEGER NOT NULL DEFAULT 0, defense_level INTEGER NOT NULL DEFAULT 0, hangar_level INTEGER NOT NULL DEFAULT 0, lab_level INTEGER NOT NULL DEFAULT 0, hull_hp INTEGER NOT NULL DEFAULT 1000, max_hull_hp INTEGER NOT NULL DEFAULT 1000, docked_ships TEXT NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());